package com.vasiliyrogozhin85.upospa;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class HardwareTestActivity extends Activity{private TextView out;public void onCreate(Bundle b){super.onCreate(b);UiKit.screen(this);setContentView(ui());run();}private View ui(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(UiKit.dp(this,16),UiKit.dp(this,16),UiKit.dp(this,16),UiKit.dp(this,24));r.setBackgroundColor(UiKit.BG);TextView h=UiKit.tv(this,"‹  Аппаратные тесты",25,UiKit.TEXT,true);h.setOnClickListener(v->finish());r.addView(h);r.addView(UiKit.tv(this,"Безопасная экспресс-проверка доступного оборудования",13,UiKit.MUTED,false));out=UiKit.tv(this,"Проверка…",14,UiKit.TEXT,false);r.addView(UiKit.card(this,out),UiKit.top(this,12));r.addView(UiKit.button(this,"Повторить тест",UiKit.CLIENT,v->run()));r.addView(UiKit.darkButton(this,"Полный JSON-отчёт",v->startActivity(new android.content.Intent(this,ReportActivity.class))));return r;}private void run(){JSONObject j=HardwareTestEngine.quick(this);out.setText("Камера: "+UiKit.yesNo(j.optBoolean("camera"))+"\nGPS: "+UiKit.yesNo(j.optBoolean("gps"))+"\nBluetooth: "+UiKit.yesNo(j.optBoolean("bluetooth"))+"\nWi‑Fi: "+UiKit.yesNo(j.optBoolean("wifi"))+"\nNFC: "+UiKit.yesNo(j.optBoolean("nfc"))+"\nДатчиков: "+j.optInt("sensor_count")+"\nБатарея: "+j.optInt("battery_percent",-1)+"%\nТок: "+j.optInt("current_now_ua")+" µA");}}
